```python
def f(N: int, M: int, bridges: List[Tuple[int, int, int]]) -> int:
    bit = {}
    child = {}
    n = [0] * (N + 1)
    f = [0] * (N + 1)
    path = [0] * (N + 1)
    for u, v, lim in bridges:
        if u not in bit:
            bit[u] = [v]
        else:
            bit[u].append(v)
        f[u] = v
        if v in child:
            child[v].append(u)
        else:
            child[v] = [u]
        n[u] = lim

    tot = 0
    for i in range(N + 1, 2 - 1, -1):
        if i not in bit and f[i]!= 0:
            cum = 0
            ans = 0
            sst = []
            while f[i]!= 0:
                if n[f[i]] > cum:
                    sst.append((cum + 1, abs(n[f[i]] - cum)))
                    cum = n[f[i]]
                    ans += n[f[i]] - 1
                f[i] = f[f[i]]
            q = [i]
            c = n[i]
            ans += (i - 1) * c
            while len(q) > 0:
                h = q.pop()
                if h in child:
                    for par in child[h]:
                        q.append(par)
                        c += n[par]
                        ans += max(0, (par - 1) * c)
            sst.sort()
            sst.reverse()
